typedef struct {float x,y,z;} BodyPoint;
static void body_project(BodyPoint p,float angle,int ox,int oy,int* x,int* y){
float c=cosf(angle),s=sinf(angle),rx=p.x*c-p.z*s,rz=p.x*s+p.z*c;float scale=40.f/(40.f+rz);*x=ox+(int)(rx*scale);*y=oy+(int)(p.y*scale+rz*.18f);}
static void body_part(Canvas*c,int ox,int oy,float angle,float x,float y,float z,float w,float h,float d,bool dark){
BodyPoint v[8];int px[8],py[8];for(int i=0;i<8;i++){v[i]=(BodyPoint){x+((i&1)?w:-w),y+((i&2)?h:0),z+((i&4)?d:-d)};body_project(v[i],angle,ox,oy,&px[i],&py[i]);}
static const uint8_t faces[6][4]={{0,1,3,2},{4,5,7,6},{0,4,6,2},{1,5,7,3},{0,1,5,4},{2,3,7,6}};
for(int k=0;k<6;k++){const uint8_t*f=faces[k];int cross=(px[f[1]]-px[f[0]])*(py[f[2]]-py[f[0]])-(py[f[1]]-py[f[0]])*(px[f[2]]-px[f[0]]);if((k==0||k==3||k==4)?cross<=0:cross>=0)continue;int lo=63,hi=0;for(int j=0;j<4;j++){if(py[f[j]]<lo)lo=py[f[j]];if(py[f[j]]>hi)hi=py[f[j]];}if(lo<0)lo=0;if(hi>63)hi=63;for(int yy=lo;yy<=hi;yy++){int l=128,r=-1;for(int j=0;j<4;j++){int u=f[j],v=f[(j+1)%4];if(py[u]==py[v])continue;if((yy>=py[u]&&yy<=py[v])||(yy>=py[v]&&yy<=py[u])){int xx=px[u]+(px[v]-px[u])*(yy-py[u])/(py[v]-py[u]);if(xx<l)l=xx;if(xx>r)r=xx;}}if(l<=r){if(l<0)l=0;if(r>127)r=127;if(l<=r){canvas_set_color(c,dark||k==2||k==3?ColorBlack:ColorWhite);canvas_draw_line(c,l,yy,r,yy);}}}canvas_set_color(c,ColorBlack);for(int j=0;j<4;j++){int u=f[j],v=f[(j+1)%4];if(px[u]>=0&&px[u]<128&&px[v]>=0&&px[v]<128&&py[u]>=0&&py[u]<64&&py[v]>=0&&py[v]<64)canvas_draw_line(c,px[u],py[u],px[v],py[v]);}}
}
static void hero(Canvas*c,unsigned phase,int action,int anim,bool armed){
int ox=64+(action==1||action==2?(8-anim)*2:0),oy=32;float swing=phase?3.f*sinf((float)(phase%8)*.785398f):0;float angle=.28f+(phase?.09f*sinf((float)(phase%8)*.785398f):0);
body_part(c,ox,oy,angle,-3,22,swing,2.5f,8,2,true);
body_part(c,ox,oy,angle,3,22,-swing,2.5f,8,2,true);
body_part(c,ox,oy,angle,0,9,0,6,13,3,false);
body_part(c,ox,oy,angle,-8,10,-swing,2,12,2,false);
body_part(c,ox,oy,angle,8,10,armed?-4:swing,2,armed?8:12,2,false);
body_part(c,ox,oy,angle,0,1,0,4,7,3,true);
if(armed){body_part(c,ox,oy,angle,9,16,-5,2,3,4,true);}
}
