int32_t gta_main(void* p){UNUSED(p);Game* g=calloc(1,sizeof(Game));if(!g)return -1;g->x=4.5f;g->y=5.5f;g->ride=-1;g->pending=-1;g->menu=1;g->loading=20;for(int i=0;i<12;i++){g->nx[i]=2.5f+(i%6)*5;g->ny[i]=i<6?11.5f:17.5f;g->alive[i]=true;}float vx[8]={3.5,7.5,12.5,32.5,29.5,13.5,28.5,11.5},vy[8]={1.5,4.5,5.5,8.5,9.5,14.5,29.5,1.5};for(int i=0;i<8;i++){g->vx[i]=vx[i];g->vy[i]=vy[i];g->va[i]=(i%4)*1.570796f;}g->q=furi_message_queue_alloc(16,sizeof(InputEvent));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);ViewPort* v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,g);Gui* gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);while(!g->quit){InputEvent e;bool got=furi_message_queue_get(g->q,&e,0)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);while(got){if(g->wheel&&e.type==InputTypeShort){if(e.key==InputKeyUp)g->weapon=0;if(e.key==InputKeyRight)g->weapon=1;if(e.key==InputKeyDown)g->weapon=2;if(e.key==InputKeyLeft)g->weapon=3;if(e.key==InputKeyOk){g->armed=g->weapon!=0;g->wheel=false;}}else if(e.type==InputTypeShort&&g->menu&&!g->loading){if(e.key==InputKeyUp)g->selection=(g->selection+2)%3;if(e.key==InputKeyDown)g->selection=(g->selection+1)%3;if(e.key==InputKeyOk){if(g->selection==2)g->quit=true;else{if(g->selection==0){g->x=4.5f;g->y=5.5f;g->cash=0;g->mission=0;g->ride=-1;g->inside=false;}g->menu=0;g->velocity=0;}}}else if(e.key==InputKeyBack&&e.type==InputTypeShort&&!g->backcombo){g->menu=1;g->selection=1;}if(e.key<6){if(e.type==InputTypePress)g->keys[e.key]=true;if(e.type==InputTypeRelease)g->keys[e.key]=false;}got=furi_message_queue_get(g->q,&e,0)==FuriStatusOk;}if(g->loading)g->loading--;if(g->menu||g->loading){furi_mutex_release(g->lock);view_port_update(v);furi_delay_ms(33);continue;}bool back=g->keys[InputKeyBack];if(back&&g->keys[InputKeyLeft]&&!g->backcombo){g->wheel=true;g->backcombo=true;}if(g->wheel){if(!back)g->backcombo=false;furi_mutex_release(g->lock);view_port_update(v);furi_delay_ms(33);continue;}bool enter=back&&g->keys[InputKeyUp];if(enter&&!g->backcombo&&g->ride<0){if(g->inside)g->inside=false;else if(g->x>28&&g->x<37&&g->y<11)g->inside=true;}if(back&&(g->keys[InputKeyUp]||g->keys[InputKeyDown]))g->backcombo=true;else if(!back)g->backcombo=false;if(g->inside||enter){furi_mutex_release(g->lock);view_port_update(v);furi_delay_ms(33);continue;}bool combo=g->keys[InputKeyDown]&&(g->keys[InputKeyOk]||back);if(combo&&!g->chord&&!g->anim){if(g->ride>=0){g->ride=-1;float ex=g->x-sinf(g->a)*.65f,ey=g->y+cosf(g->a)*.65f;if(!wall(ex,ey)){g->x=ex;g->y=ey;}}else{float best=1.44f;int near=-1;for(int i=0;i<8;i++){float ax=g->x-g->vx[i],ay=g->y-g->vy[i],d=ax*ax+ay*ay;if(d<best){best=d;near=i;}}if(near>=0){g->pending=near;g->action=near%4==2?2:1;g->anim=8;}}}g->chord=combo;bool gun=g->keys[InputKeyLeft]&&g->keys[InputKeyOk];bool shot=g->keys[InputKeyRight]&&g->keys[InputKeyOk];if((gun||shot)&&!g->firelock&&g->ride<0&&!g->anim){if(gun){g->armed=!g->armed;g->action=3;g->anim=8;}else if(g->armed){g->action=4;g->anim=4;for(int i=0;i<12;i++){float ax=g->nx[i]-g->x,ay=g->ny[i]-g->y,d=ax*cosf(g->a)+ay*sinf(g->a),side=-ax*sinf(g->a)+ay*cosf(g->a);if(g->alive[i]&&d>0&&d<5&&fabsf(side)<.4f){bool clear=true;for(float t=.1f;t<d;t+=.1f)if(wall(g->x+cosf(g->a)*t,g->y+sinf(g->a)*t))clear=false;if(clear){g->alive[i]=false;break;}}}}}g->firelock=gun||shot;if(g->anim&&!--g->anim){if(g->pending>=0){g->ride=g->pending;g->pending=-1;g->x=g->vx[g->ride];g->y=g->vy[g->ride];}g->action=0;}float turn=(g->keys[InputKeyRight]&&!shot)-(g->keys[InputKeyLeft]&&!gun);g->steer+=(turn-g->steer)*.22f;g->a+=0.66f*g->steer*(g->ride>=0?(.025f+fabsf(g->velocity)*.32f):.075f);g->cam_a+=(g->a-g->cam_a)*.20f;if(g->a>6.283185f){g->a-=6.283185f;g->cam_a-=6.283185f;}else if(g->a< -6.283185f){g->a+=6.283185f;g->cam_a+=6.283185f;}float speed=(g->ride>=0?(g->ride%4==2?.20f:.15f):g->keys[InputKeyOk]?.11f:.07f)*(g->keys[InputKeyUp]-(g->keys[InputKeyDown]&&!combo));if(g->anim||back)speed=0;g->velocity+=(speed-g->velocity)*(g->ride>=0?(speed==0?.08f:.12f):.32f);if(g->anim)g->velocity=0;if(fabsf(g->velocity)<.003f)g->velocity=0;speed=g->velocity*0.66f;if(g->jump>0)g->jump--;if(g->ride>=0&&speed>0&&map[(int)g->y][(int)g->x]=='R'&&!g->jump)g->jump=10;for(int i=0;i<8;i++){if(i==g->ride||i==g->pending||i==0)continue;float step=i%4==2?.065f:i%4==3?.032f:.045f;float nx=g->vx[i]+cosf(g->va[i])*step,ny=g->vy[i]+sinf(g->va[i])*step;float ax=nx-g->x,ay=ny-g->y;bool blocked=wall(nx,ny)||ax*ax+ay*ay<.65f;for(int j=0;j<8;j++){if(j==i)continue;float bx=nx-g->vx[j],by=ny-g->vy[j];if(bx*bx+by*by<.6f)blocked=true;}if(blocked){g->va[i]+=1.570796f;if(g->va[i]>6.283185f)g->va[i]-=6.283185f;}else{g->vx[i]=nx;g->vy[i]=ny;}}for(int i=0;i<12;i++){float t=(float)furi_get_tick()*.001f;float nx=g->nx[i]+(.018f+.004f*(i%4))*cosf(t*.4f+i),ny=g->ny[i]+.018f*sinf(t*.4f+i);if(!wall(nx,g->ny[i]))g->nx[i]=nx;if(!wall(g->nx[i],ny))g->ny[i]=ny;}float x=g->x+cosf(g->a)*speed,y=g->y+sinf(g->a)*speed;bool hit=false;if(!wall(x,g->y))g->x=x;else hit=true;if(!wall(g->x,y))g->y=y;else hit=true;if(hit)g->velocity*=.35f;if(speed!=0)g->phase++;else g->phase=0;if(g->ride>=0){g->vx[g->ride]=g->x;g->vy[g->ride]=g->y;}if(g->mission<8&&fabsf(g->x-tx[g->mission])<.9f&&fabsf(g->y-ty[g->mission])<.9f){g->cash+=250;g->mission++;}furi_mutex_release(g->lock);view_port_update(v);furi_delay_ms(33);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}